<template><section><div class="zj-summary"><span>本项目报告、报告附件和其他文件，共 {{total}} 条</span><el-button v-if="canEdit" type="primary" @click="edit()">添加文件</el-button></div><el-alert v-if="error" title="加载失败，请刷新重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="暂无关联文件"><el-table-column label="文件名称" min-width="240"><template #default="{row}"><strong>{{row.name}}</strong><div v-if="legacy(row).report_id" class="zj-sub">原报告编号：{{legacy(row).report_id}}</div></template></el-table-column><el-table-column label="分类" width="120"><template #default="{row}">{{kinds[row.kind]||row.kind}}</template></el-table-column><el-table-column label="文件" min-width="200"><template #default="{row}"><el-link v-for="(f,i) in urls(row.files)" :key="f" :href="fileUrl(f)" target="_blank" type="primary" style="display:block">查看 / 下载 {{i+1}}</el-link><span v-if="!row.files" class="zj-sub">未关联文件，保留记录待补充</span></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="edit(row)">{{canEdit?'编辑 / 详情':'详情'}}</el-button><el-button v-if="canEdit" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/><el-dialog v-model="open" title="项目关联文件" width="min(760px,96vw)" :before-close="close" :close-on-click-modal="false"><el-form ref="refForm" :model="form" label-position="top" :disabled="!canEdit||saving"><el-form-item label="名称" prop="name" :rules="[{required:true,message:'请填写名称'}]"><el-input v-model="form.name" maxlength="255"/></el-form-item><el-form-item label="分类"><el-select v-model="form.kind"><el-option v-for="(label,value) in kinds" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="关联文件"><FileUpload v-model="form.files" :limit="20" :file-type="['pdf','doc','docx','xls','xlsx','png','jpg','jpeg','zip']"/></el-form-item></el-form><el-collapse v-if="form.legacySnapshot"><el-collapse-item title="原报告信息（迁移快照）"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{pretty(form.legacySnapshot)}}</pre></el-collapse-item></el-collapse><template #footer><el-button @click="close(()=>open=false)">关闭</el-button><el-button v-if="canEdit" type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></section></template>
<script setup>
import {projectDocuments,saveProjectDocument,deleteProjectDocument} from '@/api/projectFinance';import {fileUrl} from '@/utils/files';import FileUpload from '@/components/FileUpload/index.vue';import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
const props=defineProps({projectId:[String,Number],canEdit:Boolean});const {proxy}=getCurrentInstance(),page=ref(1),rows=ref([]),total=ref(0),loading=ref(false),error=ref(false),open=ref(false),form=ref({}),refForm=ref(),saving=ref(false);let snapshot='',sequence=0;const kinds={report:'报告',report_attachment:'报告附件',other:'其他文件'};const urls=s=>(s||'').split(',').filter(Boolean);function legacy(row){try{return typeof row.legacySnapshot==='string'?JSON.parse(row.legacySnapshot):row.legacySnapshot||{}}catch{return {}}}function pretty(s){try{return JSON.stringify(typeof s==='string'?JSON.parse(s):s,null,2)}catch{return s}}
async function load(){const n=++sequence;loading.value=true;error.value=false;try{const r=await projectDocuments(props.projectId,{pageNum:page.value,pageSize:20});if(n===sequence){rows.value=r.rows;total.value=r.total}}catch{if(n===sequence){rows.value=[];error.value=true}}finally{if(n===sequence)loading.value=false}}
function edit(row){form.value=row?{...row}:{name:'',kind:'other',files:''};snapshot=JSON.stringify(form.value);open.value=true}async function close(done){if(saving.value)return;if(props.canEdit&&snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('放弃未保存的文件信息？')}catch{return false}}done();return true}
async function save(){if(saving.value||!await refForm.value.validate().catch(()=>false))return;saving.value=true;try{await saveProjectDocument(props.projectId,{...form.value});open.value=false;await load()}finally{saving.value=false}}
async function remove(row){await proxy.$modal.confirm('删除此项目文件记录？物理原件保留，历史报告快照不受影响。');await deleteProjectDocument(props.projectId,row.id);await load()}const leave=async()=>open.value?await close(()=>{}):true;onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);watch(()=>props.projectId,()=>{open.value=false;page.value=1;load()});onMounted(load);
</script>
